import idautils, ida_funcs, idc
result = []
for ea in idautils.Functions():
    name = idc.get_func_name(ea)
    if name and ('sign' in name.lower() or 'md5' in name.lower() or 'bearer' in name.lower()):
        func = ida_funcs.get_func(ea)
        size = func.size_ea - func.start_ea if func else 0
        result.append({'name': name[-100:] if len(name) > 100 else name, 'ea': hex(ea), 'size': hex(size)})
result
